const canvas = document.querySelector("canvas");
const ctx = canvas.getContext("2d");

function fit() {
  const ratio = devicePixelRatio || 1;
  canvas.width = Math.round(innerWidth * ratio);
  canvas.height = Math.round(innerHeight * ratio);
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
}
fit();
still.on("resize", fit);

let wave = new Array(128).fill(0);
let shown = wave.slice();
still.on("audio", (audio) => (wave = audio.wave));

function draw() {
  const { thickness, gain, glow, fill } = still.values;
  const w = innerWidth;
  const h = innerHeight;
  ctx.clearRect(0, 0, w, h);
  // Ease toward the newest samples so the line doesn't jitter.
  shown = shown.map((v, i) => v + ((wave[i] || 0) - v) * 0.5);
  const y = (v) => h / 2 - Math.max(-1, Math.min(1, v * gain)) * (h / 2 - thickness);
  ctx.beginPath();
  shown.forEach((v, i) => {
    const x = (i / (shown.length - 1)) * w;
    if (i === 0) ctx.moveTo(x, y(v));
    else ctx.lineTo(x, y(v));
  });
  ctx.lineJoin = "round";
  ctx.lineWidth = thickness;
  ctx.strokeStyle = still.theme.accent;
  ctx.shadowColor = still.theme.accent;
  ctx.shadowBlur = glow ? 10 : 0;
  ctx.stroke();
  if (fill) {
    ctx.lineTo(w, h / 2);
    ctx.lineTo(0, h / 2);
    ctx.closePath();
    ctx.globalAlpha = 0.18;
    ctx.fillStyle = still.theme.accent;
    ctx.fill();
    ctx.globalAlpha = 1;
  }
  requestAnimationFrame(draw);
}
draw();
